UPDATE dcs_file_review
   SET status = 'APPROVED', reviewer_id = #{reviewerId}, reviewer_name = #{reviewerName},
       review_time = CURRENT_TIMESTAMP, update_by = #{reviewerId}, update_time = CURRENT_TIMESTAMP
 WHERE tenant_id = #{tenantId}
   AND review_id = #{reviewId}
   AND status = 'PENDING'
